#!/usr/bin/env bash
# Question 5: Node drain is stuck. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q5_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q5_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q5_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl label node "${Q5_NODE}" drain-lab=yes --overwrite
for n in "worker-1" "worker-2"; do
  [[ "$n" == "${Q5_NODE}" ]] || kubectl label node "$n" drain-lab- --overwrite >/dev/null 2>&1 || true
done
kubectl apply -f - <<EOF
apiVersion: apps/v1
kind: Deployment
metadata:
  name: ${Q5_APP}
  namespace: ${Q5_NS}
spec:
  replicas: 2
  selector:
    matchLabels: { app: ${Q5_APP} }
  template:
    metadata:
      labels: { app: ${Q5_APP} }
    spec:
      nodeSelector: { drain-lab: "yes" }
      containers:
        - name: web
          image: nginx:1.27-alpine
          ports: [{ containerPort: 80 }]
          readinessProbe:
            httpGet: { path: /, port: 80 }
            periodSeconds: 5
          resources:
            requests: { cpu: 50m, memory: 32Mi }
---
apiVersion: policy/v1
kind: PodDisruptionBudget
metadata:
  name: ${Q5_APP}-pdb
  namespace: ${Q5_NS}
spec:
  minAvailable: 2
  selector:
    matchLabels: { app: ${Q5_APP} }
EOF
kubectl -n "${Q5_NS}" rollout status "deployment/${Q5_APP}" --timeout=240s

case "${Q5_FAULT}" in
  pdb-blocks-drain)
    kubectl -n "${Q5_NS}" get pdb "${Q5_APP}-pdb" >/dev/null
    kubectl get node "${Q5_NODE}" -o jsonpath='{.metadata.labels.drain-lab}' | grep -q yes
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac

kubectl uncordon "${Q5_NODE}" >/dev/null 2>&1 || true
# Prove a naive drain is blocked by the PDB while pods are pinned here.
if kubectl drain "${Q5_NODE}" --ignore-daemonsets --delete-emptydir-data --timeout=20s >/dev/null 2>&1; then
  echo "drain succeeded unexpectedly" >&2
  kubectl uncordon "${Q5_NODE}" >/dev/null 2>&1 || true
  exit 1
fi
kubectl uncordon "${Q5_NODE}" >/dev/null 2>&1 || true
kubectl -n "${Q5_NS}" get pdb "${Q5_APP}-pdb" >/dev/null
